-- ====================================================================
-- Este script:
-- 1. Inserta las 1466 cajas en la tabla 'etiquetas' con su código de barras real.
-- 2. Inserta las 1466 cajas en la tabla 'entradas' para alimentar 'Existencias'.
-- 3. Vincula cada entrada con su etiqueta correspondiente.
-- 4. Permite que en 'Salidas' el operador escanee directamente el código de barras
--    físico y el sistema identifique la caja, lote y kilos automáticamente.
-- ====================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- 1. CARGA EN ETIQUETAS

-- 2. CARGA EN ENTRADAS (EXISTENCIAS)

-- 3. AJUSTE DE AUTO_INCREMENT
ALTER TABLE etiquetas AUTO_INCREMENT = 1467;
ALTER TABLE entradas AUTO_INCREMENT = 1467;

SET FOREIGN_KEY_CHECKS = 1;

SELECT 'Inventario inicial cargado exitosamente: 1466 cajas listas para despacho en Salidas.' AS resultado;
